/**
 * What one round of a run answers its replay from: the run's attempt rows,
 * read at once when the round first asks.
 *
 * A run that parks and is woken drives its body again from the top, and every
 * step it already ran is dispatched again and answered from its attempt row.
 * Read one step at a time, that is two reads per recorded step (the surviving
 * attempts that set the attempt number, then the row itself), so a resume
 * cost grew with the run's history: on a Cloudflare Durable Object, a fresh
 * runtime per alarm over Hyperdrive, 20 replayed steps cost 23 s. The seed
 * reads every row of the run in one statement, with the journal's `recall` of
 * the run's entries, in one read transaction, and answers both questions from
 * memory.
 *
 * The rows are the run's as the round began, and they stay true for the
 * round: the round holds the run's fence, so only its own dispatches write the
 * run's attempts, and a dispatch takes its key's rows before it writes any.
 * From then on that key is answered by the store. A key the seed has no row
 * for had none when the round began, which is as true for a fresh step as for
 * a recorded one: neither costs a read.
 *
 * @since 1.0.0
 */
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Semaphore from "effect/Semaphore";
import * as AttemptProbe from "./AttemptProbe.js";
/**
 * A seed over the run's rows, or one that holds none and sends every question
 * to the store.
 *
 * @since 1.0.0
 * @category constructors
 */
export const make = (rows) => {
    if (rows === undefined)
        return { survivors: () => undefined, take: () => undefined, size: 0 };
    const byKey = new Map();
    for (const row of rows) {
        const key = byKey.get(row.stepKeyDigest);
        if (key === undefined)
            byKey.set(row.stepKeyDigest, [row]);
        else
            key.push(row);
    }
    for (const key of byKey.values())
        key.sort((left, right) => left.attempt - right.attempt);
    const taken = new Set();
    return {
        survivors: (stepKeyDigest) => taken.has(stepKeyDigest)
            ? undefined
            : AttemptProbe.tolerated(AttemptProbe.survivorsOf(byKey.get(stepKeyDigest) ?? [])),
        take: (stepKeyDigest, attempt) => {
            if (taken.has(stepKeyDigest))
                return undefined;
            taken.add(stepKeyDigest);
            const row = byKey.get(stepKeyDigest)?.find((row) => row.attempt === attempt);
            byKey.delete(stepKeyDigest);
            return Option.fromUndefinedOr(row);
        },
        size: rows.length
    };
};
/**
 * Reads the seed once, on the first ask, and answers every later ask with it.
 * Concurrent first asks wait for the one read.
 *
 * @since 1.0.0
 * @category constructors
 */
export const once = (read) => {
    const permit = Semaphore.makeUnsafe(1);
    let seed;
    return permit.withPermit(Effect.suspend(() => seed === undefined
        ? Effect.tap(read, (loaded) => Effect.sync(() => {
            seed = loaded;
        }))
        : Effect.succeed(seed)));
};
